effect.shader:
vec2 getResolution(){
  vec2 s = getTexSize(inputImg.size);
  if (s.x <= 0.0 || s.y <= 0.0) s = vec2(1920.0, 1080.0);
  return s;
}
float rand(vec2 co){ return fract(sin(dot(co.xy, vec2(12.9898,78.233))) * 43758.5453); }

void main(){
  vec2 res = getResolution();
  vec2 fragCoord = acScreenNorm * res;
  vec2 uv = acScreenNorm;

  float cellW = res.x / max(ledSizeX, 1.0);
  float cellH = res.y / max(ledSizeY, 1.0);
  vec2 cellSize = vec2(cellW, cellH);

  vec2 cellIndex = floor(fragCoord / cellSize);
  vec2 cellCenterPos = (cellIndex + 0.5) * cellSize;
  vec2 cellUVn = (fragCoord - cellCenterPos) / cellSize;

  vec2 textureUV = cellCenterPos / res;

  // ── KEY FIX: sample full RGBA so we keep the PNG alpha ──
  vec4 baseSample = texture2DCv(inputImg.texture, textureUV);
  float srcAlpha = baseSample.a;                        // PNG transparency
  vec3 baseCol = baseSample.rgb;
  baseCol = mix(baseCol, tintColor.rgb, tintAmount);

  float tBlock = floor(acTime * max(flickerSpeed, 0.0));
  float flickerRnd = rand(cellIndex + vec2(tBlock, tBlock*0.37));
  float flicker = mix(1.0 - flickerAmount, 1.0, flickerRnd);

  float dMask;
  if (int(ledShape) == 0){
    float dist = length(cellUVn);
    dMask = smoothstep(dotSize, dotSize - antialias, dist);
  } else {
    float m = max(abs(cellUVn.x), abs(cellUVn.y));
    dMask = smoothstep(dotSize, dotSize - antialias, m);
  }

  float glowMask;
  if (int(ledShape) == 0){
    float dist = length(cellUVn);
    glowMask = smoothstep(dotSize + glowSize, dotSize + glowSize - antialias, dist);
  } else {
    float m = max(abs(cellUVn.x), abs(cellUVn.y));
    glowMask = smoothstep(dotSize + glowSize, dotSize + glowSize - antialias, m);
  }

  vec3 col = baseCol * dMask * flicker;
  col += baseCol * glowBrightness * glowMask * glowAlpha;
  col *= brightness;

  // ── Multiply LED mask by the source PNG alpha ──
  float outA = max(dMask, glowAlpha * glowMask) * srcAlpha;
  gl_FragColor = vec4(col * srcAlpha, outA);
}
